const clients = new Map(); // client_id -> Map(key -> value)

export async function listTools() {
  return [
    {
      name: 'open_client',
      description: 'Open a new client with an isolated key/value map.',
      inputSchema: {
        type: 'object',
        properties: {
          client_id: { type: 'string' }
        },
        required: ['client_id'],
        additionalProperties: false
      }
    },
    {
      name: 'client_put',
      description: 'Set a key/value pair for a client.',
      inputSchema: {
        type: 'object',
        properties: {
          client_id: { type: 'string' },
          key: { type: 'string' },
          value: { type: 'string' }
        },
        required: ['client_id', 'key', 'value'],
        additionalProperties: false
      }
    },
    {
      name: 'client_get',
      description: 'Get a value for a client by key.',
      inputSchema: {
        type: 'object',
        properties: {
          client_id: { type: 'string' },
          key: { type: 'string' }
        },
        required: ['client_id', 'key'],
        additionalProperties: false
      }
    }
  ];
}

function assertNonEmptyString(value, name) {
  if (typeof value !== 'string' || value.length === 0) {
    const err = new Error(`${name} must be a non-empty string`);
    err.code = -32602;
    throw err;
  }
}

export async function callTool(name, args = {}) {
  switch (name) {
    case 'open_client': {
      assertNonEmptyString(args.client_id, 'client_id');
      if (!clients.has(args.client_id)) {
        clients.set(args.client_id, new Map());
      }
      return { content: [{ type: 'text', text: args.client_id }] };
    }
    case 'client_put': {
      assertNonEmptyString(args.client_id, 'client_id');
      assertNonEmptyString(args.key, 'key');
      assertNonEmptyString(args.value, 'value');
      if (!clients.has(args.client_id)) {
        const err = new Error('unknown client');
        err.code = -32602;
        throw err;
      }
      clients.get(args.client_id).set(args.key, args.value);
      return { content: [{ type: 'text', text: 'ok' }] };
    }
    case 'client_get': {
      assertNonEmptyString(args.client_id, 'client_id');
      assertNonEmptyString(args.key, 'key');
      if (!clients.has(args.client_id)) {
        const err = new Error('unknown client');
        err.code = -32602;
        throw err;
      }
      const store = clients.get(args.client_id);
      if (!store.has(args.key)) {
        const err = new Error('unknown key');
        err.code = -32602;
        throw err;
      }
      return { content: [{ type: 'text', text: store.get(args.key) }] };
    }
    default: {
      const err = new Error('unknown tool');
      err.code = -32602;
      throw err;
    }
  }
}
